const fs = require('fs');
const path = require('path');

const body = $input.first().json.body || $input.first().json;
const projectPath = body.project_path;
const assetDir = path.join(projectPath, 'asset');

const timelinePath = path.join(assetDir, 'base_timeline.json');
if (!fs.existsSync(timelinePath)) {
  throw new Error(`base_timeline.json not found: ${timelinePath}`);
}

const slides = JSON.parse(fs.readFileSync(timelinePath, 'utf8'));

return [{
  json: {
    project_path: projectPath,
    asset_dir: assetDir,
    slides,
    slide_count: slides.length
  }
}];

// ANALYST PROMPT — 이 블록만 수정하여 분석 지시 변경
const ANALYST_PROMPT = `당신은 유튜브 영상 연출 전문가입니다.
제공된 배경 이미지들과 슬라이드 대본을 분석하여 각 슬라이드의 시각 연출 스펙을 JSON으로 출력하세요.

## 분석 기준
1. 피사체(얼굴/캐릭터) 위치 파악 → 텍스트 배치 시 겹치지 않는 빈 영역(하늘, 여백) 탐색
2. 분위기와 색상 톤 판단 (dark/light, warm/cold_blue/neutral)
3. 핵심 구절: 대본에서 가장 짧고 강렬한 1~5개 명사구 (최대 10자). 가장 강조할 단 하나에만 [FX] 태그
4. 시각 효과: GritShake / VignetteFlash / GlitchSlice / ZoomPulse 중 선택
5. Ken Burns: zoom-center / pan-right / pan-left / zoom-out / pan-up / pan-down 중 택1

## 좌표계
캔버스 중앙 (0,0) 기준 · x 범위: -960~+960 · y 범위: -400~+400

## 입력 슬라이드
{{SLIDES_JSON}}

## 출력 형식 (JSON만, 다른 텍스트 없이)
{
  "slide_01": {
    "subject": {"center": {"x": 850, "y": 200}, "bounds": {"top": 50, "bottom": 400, "left": 600, "right": 1100}, "description": "피사체 설명"},
    "mood": "긴박감과 충격",
    "color_tone": {"brightness": "dark", "tone": "cold_blue"},
    "key_phrases": [
      {"text": "[FX] 핵심 구절", "x": -500, "y": 280},
      {"text": "보조 구절", "x": -500, "y": 160}
    ],
    "visual_effects": [{"name": "GritShake", "x": 0, "y": 0}],
    "ken_burns": {"type": "zoom-center", "reason": "이유 설명"},
    "directorial_intent": "연출 의도 설명"
  }
}`;

const ANALYST_BATCH_SIZE = 10;
const MAX_RETRIES = 3;
const RETRY_WAIT_MS = 15000;

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const data = $input.first().json;
const { slides, asset_dir: assetDir, project_path: projectPath } = data;

function bashEscape(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\$/g, '\\$')
    .replace(/`/g, '\\`');
}

function runGemini(prompt, timeoutMs) {
  return new Promise((resolve, reject) => {
    const outBufs = [], errBufs = [];
    const escaped = bashEscape(prompt);
    const proc = spawn('C:\\Program Files\\Git\\bin\\bash.exe', ['-c', `gemini --yolo "${escaped}"`], { windowsHide: true });
    const timer = setTimeout(() => { proc.kill(); reject(new Error('timeout')); }, timeoutMs);
    proc.stdout.on('data', d => outBufs.push(d));
    proc.stderr.on('data', d => errBufs.push(d));
    proc.on('close', code => {
      clearTimeout(timer);
      if (code === 0) resolve(Buffer.concat(outBufs).toString('utf8'));
      else reject(new Error(`exit ${code}: ${Buffer.concat(errBufs).toString('utf8').slice(0, 200)}`));
    });
    proc.on('error', e => { clearTimeout(timer); reject(e); });
  });
}

async function runWithRetry(prompt, retries, timeoutMs) {
  let lastErr;
  for (let i = 0; i < retries; i++) {
    try { return await runGemini(prompt, timeoutMs); } catch (e) {
      lastErr = e;
      if (i < retries - 1) await new Promise(r => setTimeout(r, RETRY_WAIT_MS));
    }
  }
  throw lastErr;
}

const batches = [];
for (let i = 0; i < slides.length; i += ANALYST_BATCH_SIZE) {
  batches.push(slides.slice(i, i + ANALYST_BATCH_SIZE));
}

const batchPromises = batches.map((batch, bIdx) => {
  const label = String(bIdx + 1).padStart(2, '0');
  const slidesForPrompt = batch.map(s => ({
    slide_id: s.slide_id, full_text: s.full_text,
    duration: s.duration, bg_image: s.bg_image
  }));
  const promptContent = ANALYST_PROMPT.replace(
    '{{SLIDES_JSON}}', JSON.stringify(slidesForPrompt, null, 2)
  );
  const imagePaths = batch
    .map(s => path.join(assetDir, s.bg_image).replace(/\\/g, '/'))
    .filter(p => fs.existsSync(p));
  const imageRefs = imagePaths.map(p => `${p} 파일을 읽어서 분석에 활용해줘.`).join('\n');
  const fullPrompt = imageRefs + '\n\n' + promptContent;

  return runWithRetry(fullPrompt, MAX_RETRIES, 300000)
    .then(stdout => ({ label, batch, stdout, error: null }))
    .catch(e  => ({ label, batch, stdout: null, error: e.message }));
});

const results = await Promise.all(batchPromises);

const analystResults = {};
const failedBatches = [];

for (const { label, batch, stdout, error } of results) {
  if (error) {
    failedBatches.push({ batch_id: `analyst_${label}`, error });
    batch.forEach(s => { analystResults[s.slide_id] = null; });
    continue;
  }
  try {
    const m = stdout.match(/\{[\s\S]*\}/);
    if (m) Object.assign(analystResults, JSON.parse(m[0]));
  } catch (_) {
    batch.forEach(s => { analystResults[s.slide_id] = null; });
  }
}

return [{
  json: {
    project_path: projectPath,
    asset_dir: assetDir,
    slides: data.slides,
    analyst_results: analystResults,
    analyst_failed: failedBatches
  }
}];

// GENERATOR PROMPT — 이 블록만 수정하여 HTML 생성 지시 변경
const GENERATOR_PROMPT = `당신은 유튜브 영상 제작 도구를 위한 HTML+GSAP 애니메이션 전문가입니다.
아래 슬라이드 스펙에 따라 각 슬라이드의 완전한 standalone HTML 파일을 생성하세요.

## 기술 상수 (절대 변경 금지)
- Canvas: 1920×1080 px (body/html: margin:0, padding:0, overflow:hidden)
- 클래스 명: .bg / .text-1 / .text-2 / .text-3 고정
- 좌표: left: calc(50% + Xpx); top: calc(50% + Ypx); (캔버스 중앙 기준)
- GSAP CDN: https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js
- #composition div에 data-composition-id="slide-NN" 필수
- data-duration 값은 해당 슬라이드의 duration(초) 사용
- 배경 이미지 경로: ../asset/IMAGE_FILENAME (상대경로, 절대경로 금지)
- Ken Burns는 .bg 요소에 GSAP으로 구현 (scale 1.0 → 1.1 등)

## 텍스트 애니메이션 가이드
- [FX] 태그 구절: 더 크고 화려한 효과 (scale pulse, color glow, 강조색)
- 일반 구절: opacity 0→1 + x/y 방향 슬라이드, 0.4~0.6s duration

## 출력 규칙
- 슬라이드별로 개별 HTML 블록 출력 (마크다운 코드펜스 절대 금지)
- 반드시 아래 마커 형식 사용:
  ===HTML_START:slide_NN===
  <!DOCTYPE html>...</html>
  ===HTML_END:slide_NN===

## 슬라이드 스펙
{{SLIDE_SPEC_JSON}}`;

const GENERATOR_BATCH_SIZE = 5;
const WAVE_SIZE = 5;
const MAX_RETRIES = 3;
const RETRY_WAIT_MS = 15000;

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const data = $input.first().json;
const { slides, asset_dir: assetDir, project_path: projectPath, analyst_results: analystResults } = data;

function bashEscape(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\$/g, '\\$')
    .replace(/`/g, '\\`');
}

function runGemini(prompt, timeoutMs) {
  return new Promise((resolve, reject) => {
    const outBufs = [], errBufs = [];
    const escaped = bashEscape(prompt);
    const proc = spawn('C:\\Program Files\\Git\\bin\\bash.exe', ['-c', `gemini --yolo "${escaped}"`], { windowsHide: true });
    const timer = setTimeout(() => { proc.kill(); reject(new Error('timeout')); }, timeoutMs);
    proc.stdout.on('data', d => outBufs.push(d));
    proc.stderr.on('data', d => errBufs.push(d));
    proc.on('close', code => {
      clearTimeout(timer);
      if (code === 0) resolve(Buffer.concat(outBufs).toString('utf8'));
      else reject(new Error(`exit ${code}: ${Buffer.concat(errBufs).toString('utf8').slice(0, 200)}`));
    });
    proc.on('error', e => { clearTimeout(timer); reject(e); });
  });
}

async function runWithRetry(prompt, retries, timeoutMs) {
  let lastErr;
  for (let i = 0; i < retries; i++) {
    try { return await runGemini(prompt, timeoutMs); } catch (e) {
      lastErr = e;
      if (i < retries - 1) await new Promise(r => setTimeout(r, RETRY_WAIT_MS));
    }
  }
  throw lastErr;
}

const batches = [];
for (let i = 0; i < slides.length; i += GENERATOR_BATCH_SIZE) {
  batches.push(slides.slice(i, i + GENERATOR_BATCH_SIZE));
}

const htmlOutputs = {};
const failedSlides = [];

for (let wStart = 0; wStart < batches.length; wStart += WAVE_SIZE) {
  const wave = batches.slice(wStart, wStart + WAVE_SIZE);

  const wavePromises = wave.map((batch, wIdx) => {
    const globalIdx = wStart + wIdx;
    const label = String(globalIdx + 1).padStart(2, '0');
    const batchSpec = batch.map(s => ({
      slide_id: s.slide_id, bg_image: s.bg_image,
      duration: s.duration, full_text: s.full_text,
      analyst_spec: analystResults[s.slide_id] || null
    }));
    const promptContent = GENERATOR_PROMPT.replace(
      '{{SLIDE_SPEC_JSON}}', JSON.stringify(batchSpec, null, 2)
    );
    const imagePaths = batch
      .map(s => path.join(assetDir, s.bg_image).replace(/\\/g, '/'))
      .filter(p => fs.existsSync(p));
    const imageRefs = imagePaths.map(p => `${p} 파일을 읽어서 분석에 활용해줘.`).join('\n');
    const fullPrompt = imageRefs + '\n\n' + promptContent;

    return runWithRetry(fullPrompt, MAX_RETRIES, 600000)
      .then(stdout => ({ label, batch, stdout, error: null }))
      .catch(e  => ({ label, batch, stdout: null, error: e.message }));
  });

  const waveResults = await Promise.all(wavePromises);

  for (const { batch, stdout, error } of waveResults) {
    if (error) {
      batch.forEach(s => failedSlides.push({
        slide_id: s.slide_id, attempts: MAX_RETRIES, error_cause: error
      }));
      continue;
    }
    const pattern = /===HTML_START:(slide_\d+)===([\s\S]*?)===HTML_END:\1===/g;
    let match;
    while ((match = pattern.exec(stdout)) !== null) {
      htmlOutputs[match[1]] = match[2].trim();
    }
  }
}

return [{
  json: {
    project_path: projectPath,
    asset_dir: assetDir,
    html_outputs: htmlOutputs,
    failed_slides: failedSlides
  }
}];

const fs = require('fs');
const path = require('path');

const data = $input.first().json;
const { project_path: projectPath, asset_dir: assetDir, html_outputs: htmlOutputs, failed_slides: failedSlides } = data;

const compositionsJsonPath = path.join(assetDir, 'hyperframes_compositions.json');
fs.writeFileSync(compositionsJsonPath, JSON.stringify(htmlOutputs, null, 2), 'utf8');

const compositionsDir = path.join(projectPath, 'hyperframes', 'compositions');
fs.mkdirSync(compositionsDir, { recursive: true });

const savedFiles = [];
for (const [slideId, html] of Object.entries(htmlOutputs)) {
  fs.writeFileSync(path.join(compositionsDir, `${slideId}.html`), html, 'utf8');
  savedFiles.push(`${slideId}.html`);
}

const report = {
  timestamp: new Date().toISOString(),
  success: Object.keys(htmlOutputs),
  failed: failedSlides
};
fs.writeFileSync(path.join(assetDir, 'hf_render_report.json'), JSON.stringify(report, null, 2), 'utf8');

return [{
  json: {
    status: 'done',
    success_count: savedFiles.length,
    failed_count: failedSlides.length,
    saved_html_files: savedFiles,
    compositions_json: compositionsJsonPath,
    failed_slides: failedSlides
  }
}];
